import sys
import json

def main():
    try:
        input_data = sys.stdin.read()
        if not input_data.strip():
            print(json.dumps(0))
            return

        data = json.loads(input_data)

        if isinstance(data, list):
            total = sum(data)
            print(json.dumps(total))
        else:
            print(json.dumps(0))
    except Exception as e:
        print(json.dumps(0), file=sys.stderr)

if __name__ == "__main__":
    main()

import json
import sys

def main():
    try:
        input_data = json.load(sys.stdin)
        if isinstance(input_data, list):
            result = [str(item).title() for item in input_data]
        else:
            result = str(input_data).title()
        print(json.dumps(result))
    except Exception as e:
        print(json.dumps({"error": str(e)}), file=sys.stderr)

if __name__ == "__main__":
    main()

import sys
import json

def rpn(tokens):
    stack=[]
    for token in tokens:
        if token in ['+','-','*','/']:
            b,a=stack.pop(),stack.pop();stack.append({'+':lambda:a+b,'-':lambda:a-b,'*':lambda:a*b,'/':lambda:a/b}[token]())
        else:stack.append(float(token))
    return stack[0]

